/* 登录界面样式保持不变 */
#loginScreen {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(13, 40, 24, 0.98);
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    z-index: 200;
    border-radius: 10px;
}

#loginScreen h1 {
    font-size: 48px;
    color: #ffd700;
    text-shadow: 0 0 20px #ffd700;
    margin-bottom: 10px;
    animation: glow 2s ease-in-out infinite alternate;
}

@keyframes glow {
    from { text-shadow: 0 0 10px #ffd700, 0 0 20px #ffd700; }
    to { text-shadow: 0 0 20px #ffd700, 0 0 40px #ffd700, 0 0 60px #ff8c00; }
}

#loginScreen .subtitle {
    color: #90ee90;
    font-size: 18px;
    margin-bottom: 40px;
}

.input-group {
    margin: 15px 0;
    text-align: center;
}

.input-group label {
    display: block;
    color: #ffd700;
    margin-bottom: 8px;
    font-size: 14px;
}

.input-group input {
    width: 280px;
    padding: 12px;
    background: rgba(0, 0, 0, 0.5);
    border: 2px solid #ffd700;
    border-radius: 8px;
    color: #fff;
    font-size: 16px;
    text-align: center;
}

.input-group input:focus {
    outline: none;
    box-shadow: 0 0 15px #ffd700;
}

.btn-group {
    display: flex;
    gap: 20px;
    margin-top: 25px;
}

.btn {
    background: linear-gradient(180deg, #2d5a3d, #1a3d2a);
    border: 2px solid #ffd700;
    color: #ffd700;
    padding: 14px 35px;
    font-size: 16px;
    cursor: pointer;
    border-radius: 8px;
    transition: all 0.3s;
    text-transform: uppercase;
    font-weight: bold;
}

.btn:hover {
    background: linear-gradient(180deg, #ffd700, #ff8c00);
    color: #1a3d2a;
    transform: scale(1.05);
    box-shadow: 0 0 20px #ffd700;
}

.btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.btn-secondary {
    background: transparent;

