/* 牌桌列表样式 */
.lobby-container {
    width: 90%;
    max-width: 800px;
    margin-top: 20px;
}

.lobby-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
    padding: 0 10px;
}

.lobby-header h2 {
    color: #ffd700;
    font-size: 24px;
}

.table-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 20px;
    margin-bottom: 30px;
}

.table-card {
    background: rgba(0, 0, 0, 0.5);
    border: 2px solid #2d5a3d;
    border-radius: 12px;
    padding: 15px;
    cursor: pointer;
    transition: all 0.3s;
    min-width: 180px;
}

.table-card:hover {
    border-color: #ffd700;
    transform: translateY(-5px);
    box-shadow: 0 10px 30px rgba(255, 215, 0, 0.2);
}

.table-card.full {
    border-color: #ff6b6b;
    opacity: 0.7;
}

.table-card.full:hover {
    cursor: not-allowed;
    transform: none;
    box-shadow: none;
}

.table-card.playing {
    border-color: #4dabf7;
}

.table-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 10px;
}

.table-id {
    color: #ffd700;
    font-size: 16px;
    font-weight: bold;
}

.table-mode-badge {
    font-size: 11px;
    padding: 2px 6px;
    border-radius: 4px;
    background: rgba(255, 215, 0, 0.2);
}

.table-mode-badge.fast {
    color: #ffd700;
}

.table-mode-badge.normal {
    color: #90ee90;
}

/* 牌桌列表中的小型圆桌布局 */
.mini-table-layout {
    position: relative;
    width: 120px;
    height: 120px;
    margin: 0 auto;
}

.mini-table-center {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: linear-gradient(135deg, #2d5a3d 0%, #1a3d2a 100%);
    border: 2px solid #ffd700;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 16px;
}

.mini-seat {
    position: absolute;
    text-align: center;
    width: 32px;
}

/* 逆时针顺序: 1(底) → 2(右) → 3(顶) → 4(左) */
.mini-seat-1 { bottom: 0; left: 50%; transform: translateX(-50%); }

